scene.add(new THREE.HemisphereLight(0xe5faff,0x637448,2.1));const sun=new THREE.DirectionalLight(0xffefcb,3.2);sun.position.set(-85,130,45);sun.castShadow=true;sun.shadow.mapSize.set(2048,2048);sun.shadow.camera.left=-140;sun.shadow.camera.right=140;sun.shadow.camera.top=140;sun.shadow.camera.bottom=-140;sun.shadow.bias=-.0002;scene.add(sun);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const grass=mat(0x77a86d),sand=mat(0xe7d59e),roadmat=mat(0x3e5554),roadline=mat(0xf4e8bd),watermat=new THREE.MeshStandardMaterial({color:0x4aaeb8,roughness:.27,metalness:.1});
const terrainGeo=new THREE.PlaneGeometry(500,500,130,130);terrainGeo.rotateX(-Math.PI/2);const p=terrainGeo.attributes.position;const height=(x,z)=>{let r=Math.sqrt(x*x+z*z);return Math.max(0,Math.sin(r*.062)*2.2+Math.sin(x*.035+z*.02)*1.3+Math.cos(z*.045-x*.018)*1.1 + Math.max(0,1-r/100)*2.5)};for(let i=0;i<p.count;i++){p.setY(i,height(p.getX(i),p.getZ(i)))}terrainGeo.computeVertexNormals();const land=new THREE.Mesh(terrainGeo,grass);land.receiveShadow=true;scene.add(land);
