// Scatter trees but leave the airstrip and roads clear
for(let i=0;i<195;i++){const ang=Math.random()*Math.PI*2,r=14+Math.random()*83,x=Math.cos(ang)*r,z=Math.sin(ang)*r;if(Math.abs(x)<8&&z>-39&&z<22)continue;if(Math.abs(z)<5&&r>62&&r<92)continue;tree(x,z,.65+Math.random()*.75,r>83&&Math.random()<.25)}
for(let i=0;i<32;i++){const a=i/32*Math.PI*2;tree(Math.cos(a)*92,Math.sin(a)*92,.75+Math.random()*.5,true)}
