// Wind turbine on the distant hill
const turbine=new THREE.Group();turbine.position.set(44,height(44,-59),-59);scene.add(turbine);cylinder(turbine,.28,.48,15,mat(0xf0eee0),0,7.5,0,10);const hub=new THREE.Group();hub.position.y=15;turbine.add(hub);cylinder(hub,.6,.6,.55,mat(0xf5f2e7),0,0,0,12).rotation.x=Math.PI/2;for(let i=0;i<3;i++){const b=box(hub,.32,6.6,.18,mat(0xf7f4e9),0,3.4,0);b.rotation.z=i*Math.PI*2/3}hub.userData.spin=true;
// Airstrip, hangar and dock
const runwayMat=mat(0x5d706e),runway=new THREE.Mesh(new THREE.PlaneGeometry(14,86),runwayMat);runway.rotation.x=-Math.PI/2;runway.position.set(0,height(0,0)+.2,-4);runway.receiveShadow=true;scene.add(runway);
for(let i=0;i<9;i++){box(scene,.35,.035,3.2,roadline,0,height(0,-39+i*8)+.25,-39+i*8)}
box(scene,17,5,11,mat(0xd9d3be),-14,height(-14,-49)+2.5,-49);const hangRoof=new THREE.Mesh(new THREE.ConeGeometry(10,4,4),roof2);hangRoof.position.set(-14,height(-14,-49)+7,-49);hangRoof.rotation.y=Math.PI/4;hangRoof.scale.set(1,.7,.7);hangRoof.castShadow=true;scene.add(hangRoof);box(scene,9,3.3,.25,mat(0x72827a),-14,height(-14,-43.4)+1.65,-43.4);
