box(scene,3,.35,18,mat(0x916f4c),-11,height(-11,100)+.5,105);for(let i=0;i<5;i++){cylinder(scene,.17,.22,2,trunkMat,-12.1,height(-12,96+i*4),96+i*4,7);cylinder(scene,.17,.22,2,trunkMat,-9.9,height(-10,96+i*4),96+i*4,7)}

