function switchMode(){if(mode==='car'){mode='plane';plane.position.copy(car.position);plane.position.y=Math.max(2,car.position.y+1);plane.rotation.set(0,car.rotation.y,0);speed=Math.max(speed,2);car.visible=false;plane.visible=true;planeHeight=plane.position.y-height(plane.position.x,plane.position.z);drivingEntity=plane;toast('BUSH PLANE READY ✦')}else{mode='car';car.position.set(plane.position.x,height(plane.position.x,plane.position.z)+.05,plane.position.z);car.rotation.y=plane.rotation.y;speed*=.45;plane.visible=false;car.visible=true;drivingEntity=car;toast('ROADSTER READY ✦')}updateHUD()}
const switchButton=document.querySelector('#switch');switchButton.addEventListener('pointerdown',e=>{e.preventDefault();switchMode()});document.querySelector('#sound').addEventListener('click',e=>{e.currentTarget.textContent=e.currentTarget.textContent==='♫'?'♪':'♫';toast('SOUND EFFECTS COMING SOON')});
// Keyboard plus press-and-hold touch controls. Pointer capture keeps controls reliable on phones.
const keyMap={ArrowUp:'forward',w:'forward',W:'forward',ArrowDown:'back',s:'back',S:'back',ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right', ' ':'brake',Shift:'brake'};
addEventListener('keydown',e=>{if(keyMap[e.key]||e.key.toLowerCase()==='e'){e.preventDefault();if(e.key.toLowerCase()==='e'&&!e.repeat)switchMode();else keys[keyMap[e.key]]=true}});addEventListener('keyup',e=>{if(keyMap[e.key])keys[keyMap[e.key]]=false});
document.querySelectorAll('[data-key]').forEach(btn=>{const k=btn.dataset.key==='throttle'?'forward':btn.dataset.key==='brake'?'brake':btn.dataset.key;const down=e=>{e.preventDefault();btn.classList.add('active');btn.setPointerCapture?.(e.pointerId);keys[k]=true};const up=e=>{e.preventDefault();btn.classList.remove('active');keys[k]=false};btn.addEventListener('pointerdown',down);btn.addEventListener('pointerup',up);btn.addEventListener('pointercancel',up);btn.addEventListener('lostpointercapture',up)});
